// 年表・編・勢力・場所・役職・家系図の英訳
OP.addEn("timeline", {
  "ev-zunesha-punishment": { when: "About 1,000 years ago", title: "Zunesha begins walking under the weight of its crime", desc: "The giant elephant Zunesha was made to walk the sea forever as punishment for a crime it is said to have once committed. It is later suggested that Zunesha was a companion of Joy Boy. The Mink Tribe's nation, the Mokomo Dukedom, is built on its back." },
  "ev-ancient-kingdom": { when: "More than about 900 years ago", title: "The Ancient Kingdom flourishes", desc: "Before the Void Century, a \"certain great kingdom\" with an advanced civilization flourished. The World Government later erased its ideas and technology from history, and even its existence is treated as taboo." },
  "ev-joy-boy-era": { when: "About 900 years ago", title: "The era of Joy Boy", desc: "Joy Boy, the central figure of the Void Century, was active in this period. Traces of his ties remain in many places, including Fish-Man Island, Zou, and the Iron Giant, and his existence is also linked to the legend of the \"Sun God Nika.\"" },
  "ev-void-century": { when: "About 900 to 800 years ago", title: "The Void Century", desc: "A 100-year period in which a great war is said to have been fought between the Ancient Kingdom and an alliance of 20 kingdoms that later became the World Government. The World Government has thoroughly hidden the records of this period, and even researching it is forbidden." },
  "ev-joy-boy-promise": { when: "About 900 years ago", title: "Joy Boy's promise to Fish-Man Island", desc: "Joy Boy left a message on a Poneglyph apologizing for failing to keep his promise to Fish-Man Island. This \"letter of apology\" was placed in the Sea Forest, where Luffy and the others later see it." },
  "ev-emet-iron-giant": { when: "About 900 years ago", title: "The Iron Giant (Emet) in operation", desc: "During the Void Century, there was an Iron Giant that is said to have fought alongside Joy Boy. Its remains lay dormant on Egghead, and it starts moving again in the main story." },
  "ev-poneglyph-creation": { when: "About 800 to 900 years ago", title: "Creation of the Poneglyphs", desc: "Poneglyphs, indestructible stones carved with the true history in ancient script, were left across the world. The Kozuki family, a clan of stonemasons, is said to have been involved in making them. Four of them are red Road Poneglyphs that point the way to Laugh Tale." },
  "ev-ancient-weapons": { when: "About 800 to 900 years ago", title: "The existence of the Ancient Weapons", desc: "The Ancient Weapons Pluton, Poseidon, and Uranus, capable of destroying the world, are said to date from the Void Century. An inscription giving Pluton's location was kept in Alabasta, and the name Poseidon was passed down to a mermaid princess of Fish-Man Island." },
  "ev-world-gov-founding": { when: "About 800 years ago", title: "Founding of the World Government", desc: "The 20 kings who defeated the Ancient Kingdom founded the World Government. Every royal family except the Nefertari family, 19 in all, moved to the Holy Land of Mary Geoise, and their descendants became the Celestial Dragons." },
  "ev-nefertari-refusal": { when: "About 800 years ago", title: "The Nefertari family refuses to move to Mary Geoise", desc: "Of the 20 founding kings, only the Nefertari family did not move to Mary Geoise. They stayed in Alabasta and kept ruling the country. This choice led to later conflicts surrounding the royal family and the Poneglyphs." },
  "ev-ryuma-legend": { when: "Date unknown (long ago)", title: "The legend of the samurai Ryuma", desc: "Ryuma, a legendary samurai of Wano Country, is remembered as a master swordsman who is said to have slain a dragon. He was buried with his sword Shusui, but his body was later used by Moria on Thriller Bark." },
  "ev-noland-jaya": { when: "About 400 years ago", title: "Noland meets Kalgara on Jaya", desc: "Montblanc Noland, an explorer from the Lvneel Kingdom, landed on Jaya and met Kalgara, a warrior of the golden city of Shandora. After Noland cured an epidemic, the two became close friends." },
  "ev-shandora-sky": { when: "About 400 years ago", title: "Shandora is launched into the sky", desc: "A Knock Up Stream sent half of Jaya into the sky, and the ruins of Shandora ended up on a sky island. When Noland returned, he could not find the golden city, and he was executed as a liar." },
  "ev-linlin-elbaph": { when: "About 63 years ago", title: "Young Linlin is left in Elbaph", desc: "The young Charlotte Linlin was taken in by Mother Carmel's \"Sheep's House\" and lived in Elbaph. After an incident at a festival, she broke with the giants, and Carmel and the others disappeared." },
  "ev-rumbar-laboon": { when: "About 52 years ago", title: "The Rumbar Pirates part with Laboon", desc: "At Twin Capes, the Rumbar Pirates promised the whale Laboon they would meet again, then entered the Grand Line. The crew was later wiped out, and only Brook, who had eaten the Revive-Revive Fruit, survived as a skeleton." },
  "ev-rocks-pirates": { when: "38 or more years ago", title: "Rise of the Rocks Pirates", desc: "The pirate crew captained by Rocks D. Xebec included Whitebeard, Big Mom, and Kaido, who later became Emperors. Its members were violent enough to fight among themselves, and the crew is said to have aimed to become king of the world." },
  "ev-god-valley": { when: "38 years ago", title: "The God Valley Incident", desc: "The Rocks Pirates ran wild on God Valley while Celestial Dragons were visiting, and the Marine Garp and the pirate Roger joined forces to destroy them. Garp came to be called a hero, and the island of God Valley vanished from the map." },
  "ev-oden-voyage": { when: "About 30 to 25 years ago", title: "Oden's voyage", desc: "Kozuki Oden left Wano Country, joined the Whitebeard Pirates, and later moved to the Roger Pirates. Unlike Whitebeard, who could not read Poneglyphs, Roger needed Oden's knowledge of the script." },
  "ev-laugh-tale": { when: "About 25 years ago", title: "Roger reaches Laugh Tale", desc: "The Roger Pirates reached the final island. They burst out laughing at the treasure and the truth left there, so they named the island \"Laugh Tale.\" Roger later disbanded the crew." },
  "ev-oden-return": { when: "About 25 years ago", title: "Oden returns to Wano Country", desc: "Back home, Oden found that Kurozumi Orochi had teamed up with Kaido and taken the shogun's seat. With his people held hostage, Oden trusted Orochi's promise and endured five years of a \"naked dance.\"" },
  "ev-roger-execution": { when: "24 years ago", title: "Execution of Pirate King Gol D. Roger", desc: "Pirate King Gol D. Roger met his end on the execution platform in Loguetown. As he died he said, \"My treasure? If you want it, I'll let you have it,\" and people around the world set out to sea." },
  "ev-great-pirate-era": { when: "24 years ago", title: "The Great Pirate Era begins", desc: "Roger's last words led many pirates to set out to sea in search of the One Piece. This was the start of the Great Pirate Era." },
  "ev-ace-birth": { when: "About 22 years ago", title: "Ace's birth and the death of his mother Rouge", desc: "Pregnant with Roger's child, Portgas D. Rouge delayed the birth for a long time to protect the child from the government's search. She died after giving birth to Ace. At Roger's request, Ace was entrusted to Garp." },
  "ev-ohara-buster-call": { when: "22 years ago", title: "The Buster Call on Ohara", desc: "Ohara, an island of archaeologists who studied the Void Century, was wiped off the map by a World Government Buster Call. The only survivor was eight-year-old Nico Robin, and a bounty was placed on her." },
  "ev-oden-execution": { when: "20 years ago", title: "Execution of Kozuki Oden", desc: "Oden realized Orochi had betrayed him and challenged Kaido with his Red Scabbard samurai, but lost and was sentenced to be boiled alive. To save his retainers, Oden endured for one hour before he died." },
  "ev-toki-time-travel": { when: "20 years ago", title: "Toki sends the retainers 20 years ahead", desc: "Using the Time-Time Fruit, Kozuki Toki sent Momonosuke and the Red Scabbard retainers 20 years into the future, and she died in the castle. She left a prophecy that Wano Country would be opened to the world in 20 years." },
  "ev-flevance": { when: "About 16 years ago", title: "The tragedy of Flevance", desc: "An illness caused by amber lead poisoning spread through the white town of Flevance. Neighboring countries mistook it for a contagious disease and destroyed the town. The young Trafalgar Law lost his family and was the only one to survive." },
  "ev-fisher-tiger-raid": { when: "About 15 to 16 years ago", title: "Fisher Tiger's raid on Mary Geoise", desc: "The fish-man Fisher Tiger stormed the Holy Land of Mary Geoise alone and freed many slaves of every race. Hancock and her sisters gained their freedom at this time." },
  "ev-sun-pirates": { when: "About 15 years ago", title: "Formation of the Sun Pirates", desc: "Tiger formed the Sun Pirates with his companions from the Fish-Man District, and Jinbe and Arlong joined. To hide the brands of the freed slaves, they flew a sun emblem on their Jolly Roger." },
  "ev-corazon-death": { when: "13 years ago", title: "Corazon's death on Minion Island", desc: "Corazon, Doflamingo's younger brother, had Law eat the Op-Op Fruit so he could cure his illness. Corazon was shot dead by his brother, and Law went on living with Corazon's wishes in his heart." },
  "ev-fisher-tiger-death": { when: "About 11 to 12 years ago", title: "Death of Fisher Tiger", desc: "After taking Koala, a former slave girl, back to her home, Tiger was badly wounded in a Navy ambush. He refused a transfusion of human blood and died, and his death widened the rift between fish-men and humans." },
  "ev-shanks-arm": { when: "12 years ago", title: "Shanks loses his arm in Foosha Village", desc: "Shanks, who was based in Foosha Village, lost his left arm saving Luffy from a Sea King. When he left the village, Shanks entrusted his straw hat to Luffy. Luffy had eaten the Gum-Gum Fruit around this time." },
  "ev-sakazuki-brothers": { when: "12 years ago", title: "Luffy, Ace, and Sabo share sake cups", desc: "Luffy was left in Dadan's care and met Ace and Sabo on Mt. Colubo. The three shared sake cups to become sworn brothers and vowed to each become free pirates." },
  "ev-sabo-incident": { when: "12 years ago", title: "The Sabo incident", desc: "After the burning of the Gray Terminal, Sabo abandoned his noble family and put out to sea, but a Celestial Dragon's ship fired on him and he disappeared. He was thought dead, but Dragon had actually saved him, and he grew up in the Revolutionary Army with no memory of his past." },
  "ev-zeff-sanji": { when: "About 12 years ago", title: "Zeff and Sanji adrift", desc: "The young Sanji, an apprentice cook on a passenger ship, was shipwrecked in a storm and starved on a rock with the pirate \"Red-Leg Zeff.\" Zeff gave Sanji his own food to keep him alive, and later opened the Baratie." },
  "ev-dressrosa-takeover": { when: "10 years ago", title: "Doflamingo seizes Dressrosa", desc: "Doflamingo used his string powers to control King Riku and make him attack his own people, destroying trust in the royal family. In the chaos, Doflamingo took the throne himself and used Sugar's powers to turn those who opposed him into toys." },
  "ev-bellemere-death": { when: "10 years ago", title: "Bell-mère's death and Arlong's rule", desc: "The Arlong Pirates landed in Cocoyashi Village and forced the villagers to pay tribute. Bell-mère was killed trying to protect Nami and Nojiko, and Nami was made to work as the Arlong Pirates' surveyor." },
  "ev-otohime-death": { when: "About 10 years ago", title: "Assassination of Queen Otohime", desc: "Queen Otohime, who was collecting signatures for a move to the surface, was assassinated. The killer was later revealed to be Hody Jones." },
  "ev-tom-arrest": { when: "About 10 years ago", title: "Tom's arrest and the birth of Franky", desc: "Tom, the shipwright who built the Sea Train, was taken away through a scheme by Spandam, using the crime of having built Roger's ship as a pretext. Cutty Flam, who tried to stop it, was hit by the train and survived as the cyborg Franky." },
  "ev-ace-sets-sail": { when: "5 years ago", title: "Ace sets sail", desc: "At 17, Ace put out to sea from near Foosha Village as promised. After the Spade Pirates, he joined the Whitebeard Pirates and became commander of the 2nd Division." },
  "ev-blackbeard-thatch": { when: "Around the start of the main story", title: "Blackbeard betrays the Whitebeard Pirates", desc: "Teach killed his crewmate Thatch to get the Dark-Dark Fruit and deserted the Whitebeard Pirates. To take responsibility as his commander, Ace set off alone in pursuit." },
  "ev-luffy-sets-sail": { when: "Main story (East Blue)", title: "Luffy sets sail", desc: "At 17, Luffy left Foosha Village in a small boat. With his promise to Shanks in his heart, his adventure to become Pirate King began." },
  "ev-zoro-joins": { when: "Main story (East Blue)", title: "Zoro joins", desc: "Luffy met Koby, who had escaped from Alvida, and in Shells Town he rescued Roronoa Zoro, who was being held by the Navy. They defeated Captain Morgan, and Zoro became Luffy's first crewmate." },
  "ev-buggy-defeated": { when: "Main story (East Blue)", title: "Buggy's defeat and meeting Nami", desc: "In Orange Town, Luffy and the others fought Buggy the Clown and beat him. Teaming up with Nami the thief led to her joining the crew later." },
  "ev-usopp-joins": { when: "Main story (East Blue)", title: "Usopp joins and the Going Merry", desc: "In Syrup Village, they stopped Captain Kuro's plan to take Kaya's mansion. Usopp joined the crew, and Kaya gave them the ship Going Merry." },
  "ev-zoro-mihawk": { when: "Main story (East Blue)", title: "Zoro loses to Mihawk", desc: "At the Sea Restaurant Baratie, Zoro challenged Mihawk, the world's greatest swordsman, and was completely beaten. Zoro swore to Luffy that he would never lose again." },
  "ev-sanji-joins": { when: "Main story (East Blue)", title: "Krieg's defeat and Sanji joins", desc: "Luffy defeated Don Krieg, who had attacked the Baratie. Sanji, who dreams of the All Blue, said goodbye to Zeff, the man who saved him, and became the crew's cook." },
  "ev-arlong-defeated": { when: "Main story (East Blue)", title: "Fall of Arlong Park and Nami joins", desc: "After Nami's tearful plea, Luffy and the others defeated the Arlong Pirates. Cocoyashi Village was freed, and Nami officially joined the crew." },
  "ev-first-bounty": { when: "Main story (East Blue)", title: "Luffy's first bounty", desc: "For defeating Arlong, Luffy was given a bounty of 30,000,000 berries. Shanks and Ace learned of Luffy's exploits from the wanted poster." },
  "ev-loguetown": { when: "Main story (East Blue)", title: "The execution platform in Loguetown", desc: "At the site of Roger's execution, Buggy nearly executed Luffy, but a lightning strike saved him. When Smoker cornered him, a mysterious man, Dragon, helped him escape." },
  "ev-laboon-promise": { when: "Main story (Grand Line)", title: "The promise to Laboon", desc: "After crossing Reverse Mountain, the crew met Laboon, a whale still waiting for his companions. Luffy promised Laboon a rematch and continued the journey." },
  "ev-whisky-peak": { when: "Main story (Grand Line)", title: "Whisky Peak and Vivi", desc: "In a town of bounty hunters, Zoro cut down 100 people. Miss Wednesday, an agent of Baroque Works, turned out to be Vivi, the princess of Alabasta, and the crew agreed to take her back to her country." },
  "ev-little-garden": { when: "Main story (Grand Line)", title: "The giants of Little Garden", desc: "On a prehistoric island, the crew met Dorry and Brogy, giants who had been dueling for 100 years. The crew drove off the Baroque Works assassins and saw the pride of Elbaph's warriors." },
  "ev-chopper-joins": { when: "Main story (Grand Line)", title: "Chopper joins", desc: "On Drum Island, where they stopped to cure Nami's illness, Luffy defeated the tyrant Wapol. Chopper, a doctor carrying on Hiriluk's wishes, joined the crew, and cherry-blossom snow fell on the island." },
  "ev-crocodile-defeated": { when: "Main story (Grand Line)", title: "Crocodile's defeat", desc: "Crocodile, one of the Seven Warlords of the Sea, was trying to take over the country and obtain Pluton. Luffy beat him on the third fight, and the civil war in Alabasta ended." },
  "ev-vivi-farewell": { when: "Main story (Grand Line)", title: "Farewell to Vivi", desc: "Vivi chose to stay in her country, and the crew said a silent goodbye by raising the X marks on their left arms. This scene is remembered as a sign of being the crew's companion." },
  "ev-ace-meets-luffy": { when: "Main story (Grand Line)", title: "Reunion with Ace", desc: "In Alabasta, Luffy met his brother Ace again. Ace was chasing the traitor Blackbeard, and he left after promising Luffy they would meet again." },
  "ev-robin-joins": { when: "Main story (Grand Line)", title: "Robin joins", desc: "Nico Robin, the former vice president of Baroque Works, came aboard the ship of Luffy, who had given her a reason to live. The crew gained an archaeologist." },
  "ev-jaya-blackbeard": { when: "Main story (Grand Line)", title: "Encounter with Blackbeard on Jaya", desc: "In Mock Town, Luffy did not fight back against Bellamy, who mocked his dream, and he happened to be in the same tavern as Blackbeard. With help from Cricket and his friends, the crew rode the Knock Up Stream toward the sky islands." },
  "ev-enel-defeated": { when: "Main story (Sky Islands)", title: "Enel's defeat and the golden bell", desc: "Luffy, a rubber man, defeated Enel, the god who ruled the sky island Skypiea. The golden bell rang for the first time in 400 years, and its sound reached the descendants of Noland and Kalgara." },
  "ev-aokiji-encounter": { when: "Main story (Grand Line)", title: "Encounter with Aokiji", desc: "After the Davy Back Fight, Navy Admiral Aokiji appeared before the crew. Aokiji, who knew about Ohara's past, targeted Robin and froze Luffy in a one-on-one fight." },
  "ev-water7-split": { when: "Main story (Water 7)", title: "The split over the Merry and Robin's departure", desc: "When the Merry was declared beyond repair, Luffy and Usopp fought a duel and parted ways. Around the same time, Robin, threatened by CP9, disappeared to protect the crew." },
  "ev-enies-lobby-war": { when: "Main story (Enies Lobby)", title: "Declaring war on the World Government and rescuing Robin", desc: "On Enies Lobby, the island of justice, Luffy had the World Government's flag shot down as a declaration of war. Robin shouted, \"I want to live,\" and Luffy defeated Lucci to get her back." },
  "ev-merry-farewell": { when: "Main story (Enies Lobby)", title: "The end of the Going Merry", desc: "The Merry, which had come to pick up the crew past its limits, was given a funeral by fire at sea. The crew said goodbye, feeling as if they had heard the Merry's last words." },
  "ev-franky-joins": { when: "Main story (Water 7)", title: "Franky joins and the Thousand Sunny", desc: "Franky gave the crew the Thousand Sunny, a ship built from the Treasure Tree Adam, and joined as shipwright. Usopp apologized and returned to the crew." },
  "ev-dragon-revealed": { when: "Main story (Water 7)", title: "Luffy's father is revealed to be Dragon", desc: "Garp, visiting Water 7, revealed that Luffy's father is the revolutionary Monkey D. Dragon. The crew was shocked, but Luffy himself knew nothing about his father." },
  "ev-banaro-island": { when: "Main story (Grand Line)", title: "The duel on Banaro Island", desc: "Ace finally caught up with Blackbeard and challenged him one-on-one on Banaro Island, but lost. Blackbeard handed Ace over to the Navy and was given a seat among the Seven Warlords of the Sea for it." },
  "ev-moria-defeated": { when: "Main story (Florian Triangle)", title: "Moria's defeat and Brook joins", desc: "On Thriller Bark, where the crew's shadows were stolen, Luffy defeated Moria as \"Nightmare Luffy.\" Brook, a skeleton musician, joined the crew to keep his promise to Laboon." },
  "ev-nothing-happened": { when: "Main story (Florian Triangle)", title: "Zoro's \"Nothing happened\"", desc: "The Warlord Kuma demanded Luffy's head, but Zoro offered himself instead and took on Luffy's pain and fatigue. Zoro did not tell the crew what had happened." },
  "ev-sabaody-dragon": { when: "Main story (Sabaody Archipelago)", title: "The Celestial Dragon punching incident", desc: "At a human auction house, Luffy punched the Celestial Dragon who had shot Hachi. Along with members of the Worst Generation who were at the auction, the crew ended up hunted by a Navy Admiral." },
  "ev-crew-scattered": { when: "Main story (Sabaody Archipelago)", title: "The Straw Hats are sent flying by Kuma", desc: "Cornered by Admiral Kizaru, Sentomaru, and the Pacifista, the crew members were sent one by one to places around the world by Kuma's power. The crew was effectively wiped out." },
  "ev-amazon-lily": { when: "Main story (Calm Belt)", title: "Amazon Lily and Hancock", desc: "Sent to Amazon Lily, Luffy learned the past of Empress Boa Hancock and won her trust. When he learned of Ace's execution, Luffy headed for Impel Down with Hancock's help." },
  "ev-impel-down-break": { when: "Main story (Impel Down)", title: "The Impel Down breakout", desc: "Luffy sneaked into the great prison and tried to rescue Ace with Buggy, Bon Clay, Ivankov, and others. Ace had already been transferred, but Luffy broke out with the prisoners. Around the same time, Blackbeard recruited prisoners from Level 6." },
  "ev-marineford-war": { when: "Main story (Summit War)", title: "The Summit War of Marineford", desc: "Over Ace's public execution, the Whitebeard Pirates clashed head-on with the Navy and the Seven Warlords of the Sea. Luffy, who had escaped Impel Down, also charged onto the battlefield to rescue his brother." },
  "ev-ace-death": { when: "Main story (Summit War)", title: "Ace's death", desc: "Ace, freed from the execution platform, was fatally wounded shielding Luffy from Akainu's attack. He died after thanking his crewmates and his brother." },
  "ev-whitebeard-death": { when: "Main story (Summit War)", title: "Whitebeard's death", desc: "Covered in wounds, Whitebeard died standing upright, with not a single wound on his back from running away. His last words were that the One Piece is real." },
  "ev-blackbeard-two-fruits": { when: "Main story (Summit War)", title: "Blackbeard takes the Tremor-Tremor Fruit", desc: "By some unknown method, Blackbeard took the power of the Tremor-Tremor Fruit from Whitebeard's body and became a user of two Devil Fruits. The war ended with no winner, and Blackbeard emerged as a new threat." },
  "ev-shanks-ends-war": { when: "Main story (Summit War)", title: "Shanks ends the war", desc: "Right after Koby's shout, Red-Haired Shanks appeared and declared the war over. Law rescued Luffy, and Shanks took charge of the funerals of Whitebeard and Ace." },
  "ev-3d2y": { when: "Main story (after the Summit War)", title: "The 3D2Y message", desc: "In despair after losing his brother, Luffy was supported by Jinbe and remembered that he had his crewmates. He reappeared at Marineford with Rayleigh and used the \"3D2Y\" on his arm to tell the crew they would regroup in two years." },
  "ev-timeskip": { when: "Main story (the two years)", title: "Two years of training", desc: "Luffy learned Haki from Rayleigh, and the crew members trained wherever they had been sent. Zoro honed his skills with Mihawk, Sanji in Kamabakka, and Nami in Weatheria." },
  "ev-akainu-fleet-admiral": { when: "Two years ago (during the training period)", title: "Akainu becomes Fleet Admiral", desc: "After Sengoku stepped down, Akainu and Aokiji fought a duel on Punk Hazard for the post of Fleet Admiral. Akainu won and became Fleet Admiral, and Aokiji, who lost, left the Navy. Navy Headquarters was moved to the New World." },
  "ev-reunion": { when: "Main story (two years later)", title: "The Straw Hats regroup", desc: "Two years later, the crew gathered again at the Sabaody Archipelago. Luffy knocked out a crowd of pirates in an instant with Haki, and the crew set sail for the New World." },
  "ev-fishman-island": { when: "Main story (two years later)", title: "The battle for Fish-Man Island", desc: "Luffy defeated Hody Jones's New Fish-Man Pirates and protected Fish-Man Island. Princess Shirahoshi was revealed to be the Ancient Weapon Poseidon, and Luffy declared war on Big Mom." },
  "ev-law-alliance": { when: "Main story (two years later)", title: "The pirate alliance with Law", desc: "On Punk Hazard, Luffy formed an alliance with the Warlord Law and joined his plan to bring down the Emperor Kaido. They captured Caesar and also met Kin'emon and Momonosuke." },
  "ev-doflamingo-defeated": { when: "Main story (two years later)", title: "Doflamingo's defeat", desc: "Luffy used Gear 4 to defeat Doflamingo, who had covered Dressrosa with his Birdcage. The people who had been turned into toys returned to normal, and the Riku royal family took the country back." },
  "ev-sabo-reunion": { when: "Main story (two years later)", title: "Reunion with Sabo and the Flame-Flame Fruit", desc: "Sabo, Chief of Staff of the Revolutionary Army, had regained his memories and met Luffy again. Sabo ate the Flame-Flame Fruit, the prize of the Colosseum tournament, and inherited Ace's power." },
  "ev-grand-fleet": { when: "Main story (two years later)", title: "Formation of the Straw Hat Grand Fleet", desc: "Seven pirate crews that fought alongside Luffy in Dressrosa declared on their own that they were becoming his subordinates. Luffy refused the subordinate sake cups, but a grand fleet of 5,600 people came into being anyway." },
  "ev-zou-revelations": { when: "Main story (two years later)", title: "The Road Poneglyph revealed on Zou", desc: "In the Mokomo Dukedom on the back of the giant elephant Zunesha, the old bond between the Minks and the Kozuki family came to light. Robin made a copy of a red Road Poneglyph that points the way to Laugh Tale." },
  "ev-whole-cake": { when: "Main story (two years later)", title: "Rescuing Sanji and escaping Whole Cake Island", desc: "To get back Sanji, who had been taken away for a political marriage, Luffy charged into Big Mom's home territory. He won a deadly fight with Katakuri, and with Jinbe's help the crew escaped." },
  "ev-fifth-emperor": { when: "Main story (two years later)", title: "\"The fifth Emperor\" and a 1.5 billion bounty", desc: "After the uproar on Whole Cake Island, the newspapers called Luffy \"the fifth Emperor.\" His bounty jumped to 1,500,000,000 berries." },
  "ev-reverie": { when: "Main story (two years later)", title: "The Reverie and the abolition of the Seven Warlords", desc: "At the Reverie held in Mary Geoise, the Seven Warlords of the Sea system was abolished. Vivi, Rebecca, Shirahoshi, and others gathered there, and Imu was shown for the first time." },
  "ev-cobra-death": { when: "Main story (two years later)", title: "Death of King Cobra", desc: "During the Reverie, King Cobra asked Imu about \"Nefertari D. Lili\" and was killed on the spot. The crime was pinned on Sabo of the Revolutionary Army, and Vivi went missing." },
  "ev-jinbe-joins": { when: "Main story (two years later)", title: "Jinbe officially joins", desc: "Having cut ties with the Big Mom Pirates, Jinbe met up with Luffy in Wano Country. He officially became the tenth member of the Straw Hat Pirates as helmsman." },
  "ev-onigashima-raid": { when: "Main story (two years later)", title: "The raid on Onigashima", desc: "Twenty years after Oden's death, the Red Scabbard samurai, the Straw Hat Pirates, and their allied pirates stormed Onigashima. Yamato, who calls himself Oden's child, joined the raid too." },
  "ev-big-mom-defeated": { when: "Main story (two years later)", title: "Law and Kid defeat Big Mom", desc: "Law and Kid used their Awakened powers to defeat the Emperor Big Mom. Around the same time, Zoro beat King and Sanji beat Queen." },
  "ev-gear5": { when: "Main story (two years later)", title: "Luffy's Awakening (Gear 5)", desc: "During the fight with Kaido, Luffy's Devil Fruit Awakened, becoming \"Gear 5.\" The fruit was revealed to be the Human-Human Fruit, Model: Nika, a Mythical Zoan that the World Government had long been pursuing." },
  "ev-kaido-defeated": { when: "Main story (two years later)", title: "Kaido's defeat and the liberation of Wano Country", desc: "Luffy defeated Kaido, and Orochi's rule also came to an end. Momonosuke became the new shogun, and Wano Country entered a new era." },
  "ev-new-emperors": { when: "Main story (two years later)", title: "A change in the Four Emperors", desc: "The defeats of Kaido and Big Mom were reported, and Luffy became a new Emperor with a bounty of 3,000,000,000 berries. At the same time, Buggy, the leader of Cross Guild, also came to be treated as one of the Emperors." },
  "ev-cross-guild": { when: "Main story (two years later)", title: "Formation of Cross Guild", desc: "Hunted after the Warlord system was abolished, Crocodile and Mihawk formed Cross Guild with Buggy as its figurehead. It became an unprecedented organization that turned the tables by placing bounties on Marines." },
  "ev-lulusia": { when: "Main story (two years later)", title: "The disappearance of the Lulusia Kingdom", desc: "The Lulusia Kingdom, which had become a base for the Revolutionary Army, was blown away in an instant by a mysterious attack from the sky. The weapon is said to have been fired from Mary Geoise, and it also contributed to the rise in sea levels around the world." },
  "ev-law-vs-blackbeard": { when: "Main story (two years later)", title: "Law loses to Blackbeard", desc: "After leaving Wano Country, Law ran into the Blackbeard Pirates on Winner Island and lost the fight between captains. The Heart Pirates were scattered." },
  "ev-shanks-vs-kid": { when: "Main story (two years later)", title: "Shanks takes out Kid with one blow", desc: "The Kid Pirates appeared in the waters near Elbaph after a Road Poneglyph, and Shanks sank them with a single blow. It was also shown that Shanks had begun moving to claim the One Piece." },
  "ev-hachinosu": { when: "Main story (two years later)", title: "Koby's rescue on Hachinosu", desc: "Garp stormed Hachinosu to rescue Koby, who had been kidnapped by the Blackbeard Pirates. Koby was rescued, but Garp stayed behind on the island after his fight with Kuzan." },
  "ev-egghead-arrival": { when: "Main story (two years later)", title: "Landing on Egghead, the island of the future", desc: "The crew arrived at Egghead, the island where the genius scientist Vegapunk has his laboratory. Vegapunk was operating as six separate bodies (the Satellites), and Bonney was traveling with the crew." },
  "ev-kuma-past": { when: "Main story (two years later)", title: "Kuma's past", desc: "Through memories that Bonney saw, the life of Kuma, who was born a slave, was revealed. He became king of the Sorbet Kingdom, joined the Revolutionary Army, and agreed to a modification that would erase his personality in exchange for treatment for his daughter Bonney." },
  "ev-kuma-marygeoise": { when: "Main story (two years later)", title: "Kuma charges through Mary Geoise", desc: "Kuma, who should have lost his personality, suddenly began to move and stormed the Holy Land of Mary Geoise. Driven only by the wish to reach his daughter Bonney, Kuma crossed the sea to Egghead." },
  "ev-egghead-incident": { when: "Main story (two years later)", title: "The Egghead Incident", desc: "To eliminate Vegapunk, Admiral Kizaru, Lucci of CP0, and Saint Saturn of the Five Elders landed on the island. Luffy fought Kizaru in Gear 5, and then all five of the Five Elders descended on the island." },
  "ev-vegapunk-broadcast": { when: "Main story (two years later)", title: "Vegapunk's worldwide broadcast", desc: "A video message Vegapunk had prepared in advance was broadcast to the whole world. It said that the use of an Ancient Weapon had raised sea levels and that the world would eventually sink into the sea, and it also revealed the name Joy Boy." },
  "ev-emet-awakens": { when: "Main story (two years later)", title: "The Iron Giant reactivates", desc: "The Iron Giant began to move in response to Luffy's Gear 5 and protected the crew from the Five Elders' attacks. The giant is said to have spoken of its memories from Joy Boy's time." },
  "ev-egghead-escape": { when: "Main story (two years later)", title: "Escape from Egghead", desc: "The original Vegapunk died in the fighting, but the crew escaped the island with help from Dorry, Brogy, and other giant warriors. Protected by the fleet of the Giant Warrior Pirates, the crew headed for Elbaph." },
  "ev-saturn-replaced": { when: "Main story (two years later)", title: "Saint Saturn's execution and Saint Garling's appointment", desc: "After his failure on Egghead, Saint Saturn was killed by Imu. Saint Garling, Supreme Commander of the Knights of God, took the empty seat among the Five Elders." },
  "ev-elbaph-arrival": { when: "Main story (two years later)", title: "Arrival at Elbaph", desc: "The Straw Hat Pirates arrived at Elbaph, the homeland of the giants. In the land of warriors Usopp had long dreamed of, the crew begins to learn about the giants' history and culture." },
  "ev-loki-meeting": { when: "Main story (two years later)", title: "Loki, the chained prince", desc: "Luffy met Loki, held in chains beneath Elbaph. Loki is said to have killed his father, King Harald, and the giants feared him as the \"cursed prince.\"" },
  "ev-saul-alive": { when: "Main story (two years later)", title: "Reunion with Saul", desc: "Jaguar D. Saul, thought to have died at Ohara, was alive in Elbaph. Robin met the man who had saved her life for the first time in 22 years." },
  "ev-holy-knights-elbaph": { when: "Main story (two years later)", title: "The Knights of God appear in Elbaph", desc: "Saint Figarland Shamrock, a man who looks exactly like Shanks, appeared in Elbaph leading the Knights of God. It has become a new source of conflict over the relationship between the World Government and the giants." }
});

OP.addEn("arcs", {
  "romance-dawn": { summary: "Luffy, a boy who ate the Gum-Gum Fruit, leaves Foosha Village for the sea, holding on to his promise to Shanks, the man who saved him. On his first voyage he meets Koby, a boy who wants to join the Navy, and in Shells Town he recruits Zoro, a swordsman held captive by the Navy. Defeating the tyrannical Navy Captain Morgan marks the real start of the Straw Hat Pirates' journey. This is the starting point of the whole story, and it shows the promise behind the straw hat." },
  "orange-town": { summary: "In Orange Town, Luffy meets Nami, a navigator who calls herself a thief. The town has been taken over by the pirate crew of Buggy the Clown, and Luffy and Zoro team up with Nami to beat Buggy. Buggy, who has the Chop-Chop Fruit, leaves the story here for a while, but he returns to its big stages many times later." },
  "syrup-village": { summary: "In Syrup Village, the crew meets Usopp, a young man who tells lies. Captain Kuro, a former pirate disguised as a butler, is carrying out a plan to attack the village and take the fortune of the young heiress Kaya. Usopp stands up to protect the village and drives off Kuro's crew together with Luffy and the others. After the fight, Usopp joins the crew, and they get their first ship, the Going Merry." },
  "baratie": { summary: "At the Sea Restaurant Baratie, Luffy meets the cook Sanji. Zoro challenges Mihawk, the strongest swordsman in the world, loses, and vows never to lose again. Don Krieg's starving pirate crew attacks the restaurant, but Luffy defeats Krieg, and Sanji says goodbye to Zeff, who raised him, and joins the crew. This arc also makes Zoro's goal and Sanji's dream of the All Blue clear." },
  "arlong-park": { summary: "Nami's hometown, Cocoyashi Village, had been ruled for years by the fish-man Arlong and his crew. Nami had served Arlong and collected money to buy back the village, but he betrays her and she asks for help. Luffy and the others storm Arlong Park and defeat the crew, and Nami officially joins. This fight earns Luffy his first bounty, and it is the first time the story shows the conflict between fish-men and humans, a major theme later on." },
  "loguetown": { summary: "The crew stops at Loguetown, where Pirate King Roger was born and also executed. Buggy nearly executes Luffy on the execution platform, but a lightning strike saves him. Navy Captain Smoker chases them, but a mysterious man (later revealed to be his father, Dragon) helps them escape, and the crew heads for the Grand Line." },
  "reverse-mountain": { summary: "The crew rides a current that flows up a mountain to cross Reverse Mountain and enter the Grand Line. At Twin Capes, they meet Laboon, a whale who has waited 50 years for his companions to return, and the lighthouse keeper Crocus. Luffy promises Laboon they will meet again, setting up Brook's later arrival in the crew." },
  "whisky-peak": { summary: "Whisky Peak, a town that welcomes pirates, was really a bounty-hunter base for the secret crime syndicate Baroque Works. Zoro breaks the town's trap single-handedly, and it turns out that Vivi, the princess of Alabasta, had infiltrated the group. The crew decides to take Vivi back to her country, and the long fight over Alabasta begins." },
  "little-garden": { summary: "On Little Garden, an island where prehistoric creatures still live, the crew meets Dorry and Brogy, giants who have been dueling for 100 years. Baroque Works assassins interfere in the duel, but the crew drives them off. Moved by the giants' pride, Usopp comes to long for Elbaph, the land of warriors." },
  "drum-island": { summary: "Nami falls seriously ill, and the crew lands on the snowy Drum Island looking for a doctor. The tyrant Wapol, who had abandoned the country and fled, has returned, and Luffy defeats him. Chopper, a blue-nosed reindeer, takes up the dream of Hiriluk, the man who saved him, and joins the crew." },
  "alabasta": { summary: "In the desert kingdom of Alabasta, Crocodile of the Seven Warlords of the Sea secretly controls Baroque Works and is pushing the country into civil war so he can take it over. Vivi and the crew race to stop the rebellion, and Luffy defeats Crocodile after losing to him twice. Crocodile's real goal is the Ancient Weapon Pluton, and this arc is where the big mysteries of the Poneglyphs and the Void Century first come into focus. After the fight, Vivi stays in her country, and Nico Robin joins the crew." },
  "jaya": { summary: "When a huge ship falls from the sky, the crew learns that sky islands exist. In Mock Town on Jaya, Luffy does not fight back against the pirate Bellamy, who laughs at his dream, and he also crosses paths with Teach, who is later revealed to be Blackbeard. Cricket, a descendant of the island's legendary explorer Noland, tells them about the city of gold, and the crew rides a current that shoots up into the sky." },
  "skypiea": { summary: "Skypiea, a country above the clouds, is ruled by Enel, who calls himself God. The crew gets caught up in a 400-year conflict between the native Shandia and the sky people while reaching the ruins of Shandora, the city of gold. Luffy, whose body is rubber, defeats Enel and his lightning powers, and rings the bell of Shandora to show Noland's honor. Robin finds writing left by Roger here, which deepens the mystery of the Poneglyphs." },
  "long-ring": { summary: "On the long, thin island of Long Ring Long Land, the Foxy Pirates challenge the crew to a Davy Back Fight with crewmates as the stakes. The crew wins, but right after that Navy Admiral Aokiji appears, overwhelms them, and leaves behind words tied to Robin's past. This short arc sets up the next big conflict." },
  "water-7": { summary: "In the shipbuilding town of Water 7, the crew is told the Merry can no longer be repaired. Luffy and Usopp fight a duel over what to do with the ship, and Usopp leaves the crew. Robin also disappears and is accused of trying to assassinate Mayor Iceburg, but the government intelligence agency CP9 was behind it. It turns out Robin had handed herself over to CP9 to protect her crewmates." },
  "enies-lobby": { summary: "The crew storms Enies Lobby, the government's island of justice, to take back Robin, who has been taken there. Robin tells of how the government destroyed her home, Ohara, and Luffy and the others shoot down the World Government's flag as a declaration of war. After a deadly fight with CP9 they rescue Robin, but the Merry gives out during the escape, and the crew parts with the ship. After the battle, Franky joins the crew, and their new ship, the Thousand Sunny, is completed." },
  "thriller-bark": { summary: "In the Florian Triangle, the crew wanders onto Thriller Bark, a giant ship. The Warlord Gecko Moria steals other people's shadows to control zombies, and Luffy and the others have their shadows stolen too. The crew defeats Moria, and Brook, a skeleton musician who carries a promise to Laboon, joins the crew. Right after the fight, the Warlord Kuma appears, and Zoro takes on Luffy's pain in his place." },
  "sabaody": { summary: "Before heading to Fish-Man Island, the crew stops at the Sabaody Archipelago to get the ship coated. Luffy sees the Celestial Dragons' abuses at the Human Shop and punches one, and Navy Admiral Kizaru is sent to the island. After meeting Rayleigh, the Dark King, the crew is sent flying to places around the world by Kuma and scattered. This arc also brings together the young pirates known as the Supernovas." },
  "amazon-lily": { summary: "Luffy is sent flying to Amazon Lily, an island where only women live. He learns the past of Empress Boa Hancock and her sisters, and keeping their secret earns him Hancock's trust. There he learns that his brother Ace's execution has been decided, and with Hancock's help he heads for the underwater prison Impel Down." },
  "impel-down": { summary: "To save Ace, Luffy sneaks into Impel Down, the world's worst prison. He works his way down through the lower levels with help from Bon Clay, Ivankov, Crocodile, Jinbe, and others, but Ace has already been transferred. Though suffering from Chief Warden Magellan's poison, Luffy pulls off a mass breakout with the prisoners. Behind the scenes, Blackbeard recruits prisoners from the lowest level." },
  "marineford": { summary: "Over Ace's execution, all-out war breaks out at Navy Headquarters in Marineford between the Whitebeard Pirates and the Navy with the Seven Warlords of the Sea. Luffy frees Ace once, but Ace dies shielding Luffy from Akainu. Whitebeard also falls in battle, and Blackbeard steals his power. At the end, Shanks appears and ends the war, and the world starts moving toward a new era." },
  "post-war": { summary: "Having lost his brother, Luffy is supported by Jinbe's words and remembers that he has his crewmates. To train in Haki under Rayleigh, Luffy returns to Marineford and sends his crew the \"3D2Y\" signal. The crew members each begin two years of training where they are, and the story moves two years ahead." },
  "return-sabaody": { summary: "After two years of training, the crew regroups at the Sabaody Archipelago. Fake Straw Hats have appeared on the island and are causing trouble, but the stronger crew drives off the Navy's Pacifista and dives to the sea floor in the coated Sunny." },
  "fishman-island": { summary: "On Fish-Man Island, 10,000 meters under the sea, the crew meets the mermaid princess Shirahoshi and the royal family. Hody Jones, driven by hatred of humans, plots to take over the country, but Luffy and the others stop him. Through the wishes of the murdered Queen Otohime and the past of Fisher Tiger, the arc looks closely at the relationship between fish-men and humans. In the Sea Forest, Joy Boy's letter of apology is found, and Shirahoshi is revealed to be the Ancient Weapon Poseidon." },
  "punk-hazard": { summary: "Now in the New World, the crew lands on Punk Hazard, an island split into fire and ice. They meet Law again, who is now a Warlord, and form a pirate alliance to bring down the Emperor Kaido. They learn that the scientist Caesar Clown has been using children in experiments, rescue the children, and capture Caesar. Kin'emon, a samurai of Wano Country, also appears here." },
  "dressrosa": { summary: "Dressrosa, the country of love and passion, is ruled by the Warlord Doflamingo. The citizens have been made to forget the people turned into toys by a Devil Fruit power, and Luffy enters a Colosseum tournament with the Flame-Flame Fruit as the prize. After a reunion with Sabo, the reveal of Law's past, and the final battle with Doflamingo, the country is freed. After the fight, many pirates offer to become Luffy's subordinates, and the Straw Hat Grand Fleet is formed." },
  "zou": { summary: "The crew arrives at Zou, the Minks' country on the back of the giant elephant Zunesha. The country has been ravaged by Jack's attack, and the old bond between the Minks and the samurai of the Kozuki family comes to light. This island also has a Road Poneglyph, and the path to the One Piece becomes concrete. Meanwhile, Sanji has been taken away for a political marriage arranged by his family, the Vinsmokes." },
  "whole-cake": { summary: "To get Sanji back, Luffy and the others charge into Whole Cake Island, home of the Emperor Big Mom. The wedding of Sanji and Big Mom's daughter Pudding was a trap to wipe out the Germa family. The crew throws the wedding into chaos and gets a copy of a Road Poneglyph, and Luffy wins a deadly fight with Katakuri and escapes the island. Jinbe also decides in this arc to join the crew." },
  "reverie": { summary: "The Reverie, a world council where kings from around the world gather at the Holy Land of Mary Geoise, is held. People with ties to the crew, such as Vivi and Shirahoshi, attend, while the Revolutionary Army moves to free Kuma, who has been made a slave of the Celestial Dragons. Behind the council, Imu, a mysterious figure who sits on the Empty Throne, appears for the first time. At the end of the council, news of the death of Alabasta's King Cobra and Vivi's disappearance shakes the world." },
  "wano": { summary: "Wano Country, closed off from the outside world, is ruled by the shogun Kurozumi Orochi and the Emperor Kaido. The samurai carrying on Kozuki Oden's wishes, the Straw Hat Pirates, and their allied pirates raid Onigashima and fight the combined forces of Kaido and Big Mom. Oden's flashback shows Roger reaching Laugh Tale, and Luffy's fruit is revealed to be the Human-Human Fruit, Model: Nika, a Mythical Zoan. Luffy defeats Kaido with his Awakened power and is counted as a new Emperor." },
  "egghead": { summary: "The crew lands on Egghead, the island of the future where the genius scientist Vegapunk has his laboratory. The government sends Kizaru, CP0, and even the Five Elders to eliminate Vegapunk, and the island becomes a fierce battlefield. Kuma's past is told from Bonney's point of view, and Vegapunk broadcasts to the world truths the government has hidden, including that the world's seas will rise and swallow the land. The original Vegapunk falls, but the crew escapes the island with the giants' help and heads for Elbaph." },
  "elbaph": { summary: "The crew arrives at Elbaph, the country of the giants, and sees the culture and history of the land of warriors Usopp has long admired. Luffy meets Loki, a prince held in chains, and learns that Saul, thought to have died at Ohara, is alive. The Knights of God, led by Saint Shamrock, who looks exactly like Shanks, also appear, and a new conflict involving the giants and the World Government is starting. This arc is still being serialized, and the story is also showing more of past events such as God Valley, so this content may change as the story continues." }
});

OP.addEn("factions", {
  "pirates": { desc: "People who sail the seas freely, plundering and seeking adventure. The World Government hunts them as bounty heads." },
  "world-gov": { desc: "The largest organization in the world, founded by 20 kingdoms 800 years ago and uniting more than 170 member countries." },
  "revolutionary-army": { desc: "An organization led by Monkey D. Dragon that aims to overthrow the World Government. Its headquarters was on Baltigo (later moved)." },
  "kingdoms": { desc: "Countries around the world, both members and non-members of the World Government." },
  "others": { desc: "People and organizations that do not belong to any side." },
  "five-elders": { desc: "Five old men said to hold the highest authority in the World Government. In fact, Imu stands above them." },
  "imu-and-knights": { desc: "Imu, a mysterious figure who sits on the \"Empty Throne\" in the Holy Land of Mary Geoise, and the Knights of God, made up of Celestial Dragons." },
  "celestial-dragons": { desc: "Descendants of the 20 kings who founded the World Government. They live in Mary Geoise and hold enormous privileges." },
  "marines": { desc: "The World Government's military organization. It upholds \"Justice\" and cracks down on pirates. Its headquarters was at Marineford (later moved)." },
  "sword": { desc: "A secret unit made up of people who have temporarily left the Navy's rolls. Koby and Drake are members." },
  "cipher-pol": { desc: "The intelligence agency directly under the World Government. It has units CP1 through CP9 and CP0 at the top." },
  "cp9": { desc: "An assassination unit that officially does not exist. The enemy in the Enies Lobby Arc." },
  "cp0": { desc: "The strongest intelligence agency, serving the Celestial Dragons directly." },
  "impel-down-staff": { desc: "The staff of Impel Down, the great underwater prison." },
  "seven-warlords": { desc: "Seven pirates sanctioned by the government. The system was abolished by a decision of the Reverie." },
  "yonko": { desc: "Four great pirates who reign over the New World. The members change over time." },
  "roger-pirates": { desc: "The crew of Pirate King Gol D. Roger. The only crew to have reached Laugh Tale." },
  "rocks-pirates": { desc: "A legendary pirate crew that existed 38 years ago. It was destroyed in the God Valley Incident." },
  "straw-hat-pirates": { desc: "The pirate crew led by Monkey D. Luffy. The main characters of the series." },
  "straw-hat-grand-fleet": { desc: "An alliance of seven pirate crews that declared on their own that they were under Luffy after the Dressrosa Arc." },
  "red-hair-pirates": { desc: "The pirate crew led by the Emperor Shanks." },
  "whitebeard-pirates": { desc: "The pirate crew that was led by Edward Newgate, \"the strongest man in the world.\" It fell apart after the Summit War." },
  "beasts-pirates": { desc: "The pirate crew that was led by the Emperor Kaido. It ruled Wano Country but was defeated." },
  "big-mom-pirates": { desc: "The pirate crew that was led by the Emperor Charlotte Linlin. It ruled Totto Land." },
  "blackbeard-pirates": { desc: "The pirate crew led by Marshall D. Teach. It rose after Whitebeard's death and became one of the Four Emperors." },
  "cross-guild": { desc: "An organization formed by Buggy, Crocodile, and Mihawk. It places bounties on Marines." },
  "worst-generation": { desc: "Eleven Supernovas, including Luffy, who gathered at the Sabaody Archipelago." },
  "heart-pirates": { desc: "The pirate crew led by Trafalgar Law." },
  "kid-pirates": { desc: "The pirate crew led by Eustass Kid." },
  "donquixote-pirates": { desc: "The pirate crew that was led by Doflamingo. It ruled Dressrosa, and Doflamingo worked behind the scenes as the underworld broker \"Joker.\"" },
  "baroque-works": { desc: "A secret crime syndicate with Crocodile as its president (Mr. 0). It aimed to take over Alabasta." },
  "buggy-pirates": { desc: "The pirate crew led by Buggy the Clown." },
  "arlong-pirates": { desc: "The pirate crew that was led by the fish-man Arlong. It ruled Cocoyashi Village in the East Blue." },
  "sun-pirates": { desc: "A pirate crew of fish-men and merfolk formed by Fisher Tiger." },
  "kuja-pirates": { desc: "The pirate crew of the warrior women of Amazon Lily, the Island of Women. Its captain is Boa Hancock." },
  "thriller-bark-pirates": { desc: "The pirate crew that was led by Gecko Moria." },
  "rumbar-pirates": { desc: "A music-loving pirate crew that Brook once belonged to. Laboon's companions." },
  "other-pirates": { desc: "Pirates not classified above." },
  "alabasta-kingdom": { desc: "A large desert country in the Grand Line, ruled by the Nefertari family." },
  "wano-country": { desc: "A closed country that is not a member of the World Government, protected by samurai. It was ruled by the Kozuki family." },
  "kozuki-family": { desc: "Kozuki Oden of Wano Country's shogun family and his retainers." },
  "dressrosa-kingdom": { desc: "The country of love, passion, and toys, ruled by the Riku royal family." },
  "ryugu-kingdom": { desc: "The undersea kingdom that rules Fish-Man Island, under the Neptune royal family." },
  "mink-tribe": { desc: "The Minks' country, where they live on the back of the giant elephant Zunesha." },
  "drum-kingdom": { desc: "A country on a winter island. After Wapol's tyranny, Dalton became king." },
  "elbaph-giants": { desc: "The giants who live in Elbaph, the land of warriors." },
  "skypiea-people": { desc: "The sky people and the Shandia who live in and around Skypiea." },
  "germa-66": { desc: "The army of the Germa Kingdom, a country with no land that travels the seas. It is led by the Vinsmoke family." },
  "egghead-lab": { desc: "The genius scientist Vegapunk and his separate bodies (the Satellites)." },
  "civilians": { desc: "People who do not belong to any particular organization." }
});

OP.addEn("places", {
  "foosha-village": { desc: "A small village in the East Blue that belongs to the Goa Kingdom, and Luffy's hometown. Here the young Luffy met Shanks, who saved his life but lost his left arm doing so. Luffy was entrusted with the straw hat, and his journey to become Pirate King began in this village." },
  "mt-colubo": { desc: "A mountain behind Foosha Village and the hideout of Curly Dadan's family of mountain bandits. Luffy, left there by Garp, met Ace and Sabo here, and they shared sake cups to become sworn brothers." },
  "goa-kingdom": { desc: "A kingdom in the East Blue whose territory includes Foosha Village and Mt. Colubo. It is called \"the most beautiful country in the East Blue.\" Behind that beauty it casts aside its poor, and Sabo, born into a noble family, hated that and ran away from home." },
  "gray-terminal": { desc: "A garbage heap outside the walls of the Goa Kingdom, where people with nowhere else to go lived. The kingdom set it on fire to prepare for a Celestial Dragon's visit, and Dragon, who happened to be there, saved the people. Around this time, Sabo was fired on by a Celestial Dragon's ship and went missing." },
  "shells-town": { desc: "A port town with the Navy's 153rd Branch. The tyrannical Captain Morgan ruled the town, and Luffy rescued Zoro, who had been tied to a post, and made him his first crewmate. Koby joins the Navy here." },
  "orange-town": { desc: "A town that had been taken over by the Buggy Pirates, led by Buggy the Clown. Here Luffy met Nami, defeated Buggy, and freed the town." },
  "syrup-village": { desc: "A quiet village and Usopp's hometown. Kuro of the Black Cat Pirates, disguised as a butler, was after the fortune of the young lady Kaya, and Usopp, Luffy, and the others stopped him. Kaya gave them the Going Merry as thanks." },
  "baratie": { desc: "A restaurant ship at sea run by Zeff, a cook and former pirate. It is also where Zoro challenged Hawk Eyes Mihawk, lost, and vowed to become the world's greatest swordsman. After Don Krieg's attack was driven off, Sanji joined the crew." },
  "cocoyasi-village": { desc: "Nami and Nojiko's hometown in the Konomi Islands, a village with tangerine groves. Their adoptive mother Bell-mère was killed by Arlong, and the Arlong Pirates ruled the village for eight years." },
  "arlong-park": { desc: "The base the fish-man Arlong built in the Konomi Islands. Nami was forced to draw sea charts here to buy back her village, but Luffy and the others defeated the Arlong Pirates and brought the building down." },
  "shimotsuki-village": { desc: "The village where Zoro spent his childhood, competing with his childhood friend Kuina at a sword dojo. Kuina's death led Zoro to take on the promise to become the world's greatest swordsman. The village's name and its line of swordsmanship also have ties to Wano Country." },
  "loguetown": { desc: "Called \"the town of the beginning and the end,\" this is where Pirate King Gol D. Roger was executed. Buggy nearly executed Luffy on the same platform, but a lightning strike and Dragon's intervention saved him. Smoker and Tashigi make their first appearance here." },
  "tequila-wolf": { desc: "An island with an enormous bridge that has been under construction for 700 years, where laborers are worked like slaves. Robin, sent flying by Kuma at the Sabaody Archipelago, ended up here and was later rescued by the Revolutionary Army." },
  "flevance": { desc: "The \"White Town,\" which grew rich from mining amber lead, and Law's hometown. When \"amber lead syndrome,\" caused by the poison in amber lead, spread, neighboring countries destroyed the whole country. Law was the only survivor." },
  "lvneel": { desc: "The home country of the explorer Montblanc Noland. Noland reported to the king that he had seen the city of gold on Jaya, but that part of the island had vanished into the sky, so he was executed as a liar." },
  "minion-island": { desc: "The island where a deal over the Op-Op Fruit took place. Corazon, also known as Rosinante, had Law eat the fruit to cure his amber lead syndrome, and was himself shot dead by Doflamingo." },
  "spider-miles": { desc: "A run-down port town in the North Blue where the young Doflamingo's crew had its hideout. Law, as a boy full of destructive urges, came here and joined the crew." },
  "germa-kingdom": { desc: "A kingdom that once conquered the North Blue. It no longer has any land and exists on a fleet of ships pulled by giant snails. It is ruled by the Vinsmoke family and has an army of modified human soldiers. Sanji was born a prince of this country." },
  "ohara": { desc: "An island of archaeologists with a giant library called the Tree of Knowledge, and Robin's hometown. Because it studied the Void Century, it was burned by a World Government Buster Call. Saul helped Robin escape, and she was the only survivor." },
  "baterilla": { desc: "The island where Portgas D. Rouge lived. To protect Roger's child, Rouge carried him for 20 months, then died after giving birth to Ace." },
  "sorbet-kingdom": { desc: "A country in the South Blue where Kuma was king. His people loved him, but he was later driven from the throne. It is also where Kuma and his daughter Bonney lived together." },
  "god-valley": { desc: "An island that was the site of the Celestial Dragons' \"human hunt\" 38 years ago. The Rocks Pirates attacked, and Roger and Garp joined forces to defeat them. After the incident the island disappeared from the map, and the truth was kept hidden for a long time." },
  "reverse-mountain": { desc: "A mountain rising from the Red Line. Currents from the four seas rush up its canals, meet at the summit, and pour down into the Grand Line. It is one of the entrances to the Grand Line." },
  "mary-geoise": { desc: "The World Government's base on top of the Red Line, where the Celestial Dragons live. It is the venue of the Reverie, and deep inside Pangaea Castle, Imu reigns from the Empty Throne. Fisher Tiger's freeing of the slaves also took place here." },
  "twin-capes": { desc: "A cape at the foot of Reverse Mountain, home to the lighthouse keeper Crocus and the whale Laboon. Laboon has waited more than 50 years for his companions to return, and Luffy promised to meet him again." },
  "namakura-island": { desc: "An island where the Long-Arm Tribe lives. Brook, sent flying by Kuma, was captured as a demon, but he went on to become a huge hit in a show business act and made his name as the \"Soul King.\"" },
  "whisky-peak": { desc: "An island lined with cactus-shaped rocks. Its town, which welcomed pirates, was really a nest of Baroque Works bounty hunters. Zoro cut down 100 people in one night, and Vivi's true identity was revealed." },
  "little-garden": { desc: "A jungle island where prehistoric creatures live. Dorry and Brogy, giant warriors of Elbaph, had been dueling there for 100 years, and the crew was moved by their pride. The fights with Mr. 3 and other Baroque Works agents also took place here." },
  "torino-kingdom": { desc: "An island where giant birds live. Chopper, sent flying by Kuma, ended up here and spent two years studying its medicinal herbs and other things to improve his medical skills." },
  "drum-island": { desc: "A winter island covered in snow all year round, home to the Drum Kingdom, once a great medical power. After the tyrant Wapol fled, the crew came here to get Nami treated and met Chopper. Hiriluk's cherry blossoms colored the sky, and the country later renamed itself the Sakura Kingdom." },
  "rainbase": { desc: "An oasis town in the Alabasta desert, where Crocodile's casino \"Rain Dinners\" stands. Luffy challenged Crocodile here and lost their first fight." },
  "alabasta": { desc: "A large desert country ruled by the Nefertari family. Crocodile of the Seven Warlords of the Sea used Baroque Works to try to take over the country, and with its rain stolen, the country was pushed to the edge of civil war. Luffy and the others defeated Crocodile, and the rain returned." },
  "alubarna": { desc: "The capital of the Alabasta Kingdom, where the royal palace stands. It was the site of the final battle between the rebel army and the royal army, and Luffy won his last fight with Crocodile in the royal tomb. A Poneglyph lay in the tomb." },
  "baltigo": { desc: "An island of white earth where the Revolutionary Army had its headquarters. Robin spent two years here with the Revolutionary Army. It was later attacked by the Blackbeard Pirates, and the headquarters had to be moved." },
  "jaya": { desc: "The island where Noland and Kalgara once met and where the city of gold stood. Half of the island was blown into the sky by a Knock Up Stream, and the crew came here looking for a way to the sky islands." },
  "mock-town": { desc: "A lawless town on Jaya where pirates who mock dreams gather. In a tavern, Luffy and Zoro first met Teach, who is Blackbeard." },
  "banaro-island": { desc: "The island where Ace cornered Teach, who had murdered a crewmate, and fought him in a duel. Blackbeard won, and Ace was handed over to the Navy, which set off the Summit War." },
  "long-ring-long-land": { desc: "At high tide it splits into several islands, and at low tide it becomes one long, thin island. The crew played a Davy Back Fight against the Foxy Pirates, and afterward Aokiji appeared and froze Robin." },
  "karakuri-island": { desc: "The island where the Future Country Baldimore is located, and Vegapunk's birthplace. Franky, sent flying by Kuma, studied the designs left in Vegapunk's laboratory and modified his own body." },
  "kuraigana-island": { desc: "The site of the fallen Shikkearu Kingdom, where Mihawk lives in an old castle. Zoro, sent flying by Kuma, bowed his head to his rival Mihawk, became his student, and trained for two years." },
  "water-seven": { desc: "A shipbuilding city crossed by canals, home to Galley-La Company, the world's top shipbuilding company. Luffy and Usopp fought a duel over repairing the Merry, and this was where the chase after Robin, taken away by CP9, began." },
  "enies-lobby": { desc: "An island of justice where it is always daytime, with the World Government's courthouse and Tower of Law. The crew shot down the World Government flag to declare war and took Robin back. The island was burned in a Buster Call." },
  "boin-archipelago": { desc: "Jungle islands overgrown with dangerous plants and animals. Usopp, sent flying by Kuma, studied under Heracles here and learned to fight with plants such as Pop Greens." },
  "thriller-bark": { desc: "A giant pirate ship drifting through the Florian Triangle and Gecko Moria's base. Moria put stolen shadows into zombies and controlled them. The crew recruited Brook here, and Zoro took on pain to protect his crewmates from Kuma." },
  "kamabakka-kingdom": { desc: "An \"okama paradise\" on Momoiro Island and Ivankov's homeland. Sanji, sent flying by Kuma, spent two years here and learned attack cooking and fighting. It later became the Revolutionary Army's new base." },
  "marineford": { desc: "The island where Navy Headquarters used to be. It was the site of the Summit War, in which the Whitebeard Pirates and the Navy clashed over Ace's public execution, and both Ace and Whitebeard died here. After the war, headquarters was moved to the New World." },
  "sabaody": { desc: "Islands of Yarukiman Mangrove trees, with coating craftsmen for ships heading to Fish-Man Island. When Luffy punched a Celestial Dragon, Admiral Kizaru was sent in, and Kuma's power scattered the crew. Two years later, the crew gathered here again." },
  "rusukaina": { desc: "An uninhabited island in the Calm Belt with a harsh climate where the seasons change rapidly. After the Summit War, Luffy trained in Haki here under Rayleigh." },
  "amazon-lily": { desc: "A country of women in the Calm Belt and the home of the Kuja Pirates. Luffy, sent flying by Kuma, washed up here and headed for Impel Down with Empress Hancock's help." },
  "weatheria": { desc: "A sky island where old scholars who study the weather live. Nami, sent flying by Kuma, spent two years here learning the science of weather and got a new Clima-Tact." },
  "angel-island": { desc: "An island floating on the White-White Sea where the people of Skypiea live. The crew unknowingly entered a sacred area and became a target of God's judgment." },
  "skypiea": { desc: "A sky island country floating on the White-White Sea, 10,000 meters above Jaya. The god Enel ruled through fear, and the sky people had fought the Shandia over the land for 400 years. Luffy defeated Enel and rang the golden bell." },
  "upper-yard": { desc: "A part of Jaya that was blown into the sky, and God's island, the Shandia's homeland. The ruins of Shandora, the city of gold, remain there, and it was the stage of a survival game that included Enel." },
  "birka": { desc: "A sky island said to be Enel's homeland. Enel is said to have destroyed it before coming to Skypiea." },
  "impel-down": { desc: "The World Government's great prison beneath the sea in the Calm Belt, with hellish punishments on each level. Luffy broke in to rescue Ace and escaped with many prisoners. Blackbeard used the chaos to recruit prisoners from Level 6." },
  "fishman-district": { desc: "A lawless area on the outskirts of Fish-Man Island. Many fish-men, including Arlong, Jinbe, and Fisher Tiger, came from here, and resentment toward humans ran deep in this place." },
  "fishman-island": { desc: "A country of fish-men and merfolk on the sea floor 10,000 meters down, lit by the Sun Tree Eve. Luffy and the others stopped the rebellion of Hody's New Fish-Man Pirates, and their bond with Jinbe grew deeper." },
  "ryugu-palace": { desc: "The royal palace of the Ryugu Kingdom, where King Neptune and Princess Shirahoshi live. Shirahoshi was revealed to be the Ancient Weapon Poseidon herself." },
  "sea-forest": { desc: "An undersea forest where sunken ships drift in, and the site of Queen Otohime's grave. It holds a Poneglyph carved with Joy Boy's letter of apology to the mermaid princess, which Robin deciphered." },
  "new-marine-hq": { desc: "Navy Headquarters as moved after the Summit War to the former site of the G-1 Branch. It sits at the entrance to the New World, on the opposite side of the Red Line from Marineford, and a new system was set up there under Fleet Admiral Akainu." },
  "punk-hazard": { desc: "An island half covered in fire and half in ice. Vegapunk once had a laboratory here, and the island took this form as a result of Akainu and Aokiji's fight for the post of Fleet Admiral. Luffy formed a pirate alliance with Law and captured Caesar." },
  "sphinx": { desc: "The hometown of Whitebeard, Edward Newgate. Whitebeard supported his hometown with the fortune he left behind, and Marco stayed on the island as a doctor to watch over the village." },
  "dressrosa": { desc: "The country of love, passion, and toys. Ten years ago Doflamingo took the country from the Riku royal family, turned people into toys, and erased them from memory. Luffy defeated Doflamingo, and the Riku royal family returned to the country." },
  "green-bit": { desc: "An island of the Tontatta dwarves, connected to Dressrosa by an iron bridge. It was the site of the deal between Law and Doflamingo, and Fujitora stepped in by dropping a meteorite." },
  "zou": { desc: "The Minks' country on the back of the giant elephant Zunesha, which has been walking for more than 1,000 years. After Jack's attack, the crew learned here of the bond between the Kozuki family and the Minks and obtained a Road Poneglyph." },
  "hachinosu": { desc: "A pirate island that was once the base of the Rocks Pirates and is now the home of the Blackbeard Pirates. Garp stormed it with SWORD to rescue the captured Koby." },
  "whole-cake-island": { desc: "The central island of Totto Land, ruled by Big Mom, where a castle made of sweets stands. Luffy and the others came here over the wedding of Sanji and Pudding, and the plan to assassinate Big Mom was carried out." },
  "cacao-island": { desc: "One of the islands of Totto Land, with a town made of chocolate. After winning his deadly fight with Katakuri in the mirror world, Luffy escaped from this island." },
  "flower-capital": { desc: "The capital of Wano Country, where the shogun's castle stands. Kurozumi Orochi held on as shogun, and outside the glamorous town the people suffered in poverty." },
  "wano": { desc: "A closed country surrounded by waterfalls and protected by samurai. After Kozuki Oden's execution, Kaido and Orochi ruled it for 20 years. Luffy and the others carried out the raid with the Nine Red Scabbards and others, and opened the country." },
  "kuri": { desc: "One of the regions of Wano Country, once a lawless land. Kozuki Oden became its daimyo, brought its rough men together, ruled it, and built Oden Castle." },
  "onigashima": { desc: "The home of the Beasts Pirates, off the coast of Wano Country. The raid on the night of the Fire Festival made it the site of the decisive battle, where Luffy defeated Kaido and Law and Kid defeated Big Mom." },
  "egghead": { desc: "The island where Vegapunk's laboratory is located, also called the Island of the Future. It is a winter island by nature, but science keeps it in permanent summer. When the World Government moved to eliminate Vegapunk, Saturn of the Five Elders and Admiral Kizaru landed there." },
  "karai-bari-island": { desc: "The base of Cross Guild, which has Buggy as its public face. Cross Guild places bounties on Marines and made its name as an organization opposed to the Navy." },
  "elbaph": { desc: "The country of the giant warriors, and the island of warriors Usopp has long admired. The giant Treasure Tree Adam rises there. Prince Loki is held captive there, and the crew is getting closer to the island's secrets." },
  "lodestar-island": { desc: "The last island of the Grand Line that can be reached with an ordinary Log Pose. The Roger Pirates got this far, but going on to Laugh Tale required the Road Poneglyphs." },
  "laugh-tale": { desc: "The island at the very end of the Grand Line. Only the Roger Pirates reached it, and Roger named it \"Laugh Tale\" because they burst out laughing at the treasure they found there. It lies at the place the four Road Poneglyphs point to, and the One Piece is said to rest there." }
});

OP.addEn("positions", {
  "pos-yonko": { desc: "Four great pirates who reign over the New World. It is not an official post but a title that the public and the government use in recognition of their power. When one of them falls, the seat changes hands quickly.",
    holders: [
      { note: "Died in the Summit War" },
      { note: "Defeated by Luffy on Onigashima" },
      { note: "Defeated by Kid and Law on Onigashima" },
      {},
      { note: "Took Whitebeard's territory and came to be called an Emperor during the two years" },
      { note: "Given a bounty as a new Emperor after defeating Kaido" },
      { note: "Treated as an Emperor after forming Cross Guild and because of others' misunderstandings" }
    ] },
  "pos-warlords": { desc: "Seven pirates whose piracy was sanctioned by the World Government. In return for cooperating with the government, their bounties were frozen. A resolution at the Reverie abolished the system itself.",
    holders: [
      { note: "Stripped of the title after his plan to take over Alabasta was exposed" },
      { note: "Remained a member until the system was abolished" },
      { note: "Remained a member as a government weapon even after his modification" },
      {},
      { note: "Stripped of the title after his defeat in Dressrosa" },
      {},
      { note: "Gave up the title to side with Whitebeard and was imprisoned" },
      { note: "Joined to fill an empty seat and gave it up when he raided Impel Down" },
      { note: "Joined during the two years. Stripped of the title after Dressrosa" },
      { note: "Joined after escaping Impel Down" }
    ] },
  "pos-admirals": { desc: "The Navy's highest fighting strength, ranked just below the Fleet Admiral. There are normally three, and all of them are monsters with Logia or other powerful abilities.",
    holders: [
      { note: "Lost his duel with Akainu for the post of Fleet Admiral and left the Navy" },
      { note: "Promoted to Fleet Admiral" },
      {},
      { note: "Appointed through the World Military Draft" },
      { note: "Appointed through the World Military Draft" }
    ] },
  "pos-fleet-admiral": { desc: "The highest rank in the Navy. The Fleet Admiral commands the Admirals and decides the policy of the whole Navy.",
    holders: [
      { note: "Retired after the Summit War and became Inspector General" },
      {}
    ] },
  "pos-elders": { desc: "Five old men said to hold the highest authority in the World Government. In reality, Imu reigns above them.",
    holders: [
      { note: "Failed his mission on Egghead and was executed by Imu" },
      {},
      {},
      {},
      {},
      { note: "Saint Saturn's successor" }
    ] }
});

OP.addEn("families", {
  "fam-monkey-d": { desc: "A bloodline in which three generations, the Navy hero Garp, Dragon of the Revolutionary Army, and the pirate Luffy, all affect the course of the world. Ace and Sabo are sworn brothers who shared sake cups with Luffy and are not related to him by blood.",
    members: { ace: { note: "Sworn brother (his real father is Roger)" }, sabo: { note: "Sworn brother" } } },
  "fam-gol-d": { desc: "Pirate King Roger and Rouge, who gave birth to his child at the cost of her life. Ace used his mother's surname to hide his origins from the world." },
  "fam-charlotte": { desc: "The large family built by Linlin, known as Big Mom. She has more than 85 children, and the siblings, who have different fathers, are sent around the world as pieces in political marriages. Only the main children are listed here.",
    members: {
      perospero: { note: "Eldest son" },
      "x-compote": { note: "Eldest daughter" },
      "x-daifuku": { note: "Eldest of the triplets" },
      oven: { note: "Triplet" },
      katakuri: { note: "Triplet" },
      "x-brulee": { note: "Katakuri's younger sister" },
      "x-lola": { note: "Twin of Chiffon" },
      "x-chiffon": { note: "Twin of Lola" },
      bege: { note: "Son-in-law" },
      pudding: { note: "Has the blood of the Three-Eye Tribe" }
    } },
  "fam-vinsmoke": { desc: "The royal family of the Germa Kingdom. Judge had his children's Lineage Factors modified to make them into weapons without emotions. Because their mother Sora resisted, only Reiju and Sanji kept their human hearts.",
    members: {
      "x-sora": { note: "Deceased" },
      reiju: { note: "Eldest daughter" },
      ichiji: { note: "Eldest of the quadruplets" },
      niji: { note: "Quadruplet" },
      sanji: { note: "Quadruplet (third son)" },
      yonji: { note: "Quadruplet" }
    } },
  "fam-kozuki": { desc: "The shogun family of Wano Country. Oden was executed for seeking to open the country, and 20 years later his children Momonosuke and Hiyori took the country back. Toki used her power to cross time to send her children into the future.",
    members: { "x-sukiyaki": { note: "Previous shogun" } } },
  "fam-kaido": { desc: "Kaido of the Beasts and his only child, Yamato. Yamato admired Oden, called himself \"Oden,\" and defied his father." },
  "fam-nefertari": { desc: "The royal family of Alabasta. Their ancestors were one of the kings who created the World Government 800 years ago, but they refused to move to the Holy Land of Mary Geoise. The generations between Lili and Cobra are omitted.",
    members: {
      "x-lili": { note: "Queen about 800 years ago (Cobra's ancestor)" },
      cobra: { note: "Descendant of Lili" },
      "x-titi": { note: "Deceased" }
    } },
  "fam-donquixote": { desc: "A family of Celestial Dragons. When their father Homing chose to live as an ordinary human, the family was persecuted, and the elder son Doflamingo killed his father. The younger son Rosinante became a Marine and stood in his brother's way.",
    members: {
      "x-homing": { note: "Former Celestial Dragon. Killed by his eldest son" },
      doflamingo: { note: "Eldest son" },
      corazon: { note: "Second son" }
    } },
  "fam-figarland": { desc: "A prominent Celestial Dragon family. Saint Garling is the former Supreme Commander of the Knights of God and later became one of the Five Elders. Shamrock, who leads the Knights, is said to be Shanks's identical twin.",
    members: {
      shamrock: { note: "Said to be Shanks's older twin brother" },
      shanks: { note: "The story suggests he is Garling's son. Roger took him in at God Valley" }
    } },
  "fam-nico": { desc: "A mother and daughter, archaeologists from Ohara. Olvia left the island to pursue the Poneglyphs, and on the day of the Buster Call she helped her daughter Robin escape and died." },
  "fam-neptune": { desc: "The Neptune family, which rules Fish-Man Island. Queen Otohime kept calling for coexistence with the surface world and was assassinated. The youngest daughter, Shirahoshi, has the power of the Ancient Weapon Poseidon.",
    members: {
      "x-fukaboshi": { note: "Eldest son" },
      "x-ryuboshi": { note: "Second son" },
      "x-manboshi": { note: "Third son" },
      shirahoshi: { note: "Eldest daughter" }
    } },
  "fam-elbaph": { desc: "The royal family of Elbaph, the country of the giants. The former king Harald tried to change the country, but in the end he was killed by his son Loki." },
  "fam-kuma": { desc: "Bonney is the child Ginny conceived while held by a Celestial Dragon, and she is not related to Kuma by blood. Even so, Kuma raised her as her father and gave up everything he had for her.",
    members: { kuma: { note: "Adoptive father" }, bonney: { note: "Raised by Kuma as his daughter" } } },
  "fam-usopp": { desc: "Yasopp, the sniper of the Red Hair Pirates, went to sea, and his wife Banchina raised their son in their hometown. His mother died of illness, and Usopp grew up proud of his father.",
    members: { "x-banchina": { note: "Deceased" } } }
});
